fungsi cari_binari(s: Senarai<Nombor>, sasaran: Nombor) -> Mungkin<Nombor> kesan Bersih {
    biar ubah kiri = 0;
    biar ubah kanan = s.panjang() - 1;
    selagi kiri <= kanan {
        biar tengah = (kiri + kanan) / 2;
        kalau s[tengah] == sasaran {
            pulang Ada(tengah);
        } lain kalau s[tengah] < sasaran {
            kiri = tengah + 1;
        } lain {
            kanan = tengah - 1;
        }
    }
    Tidak
}

