fungsi kumpul_mengikut(
    s: Senarai<(Teks, Nombor)>
) -> Senarai<(Teks, Senarai<Nombor>)> kesan Bersih {
    biar ubah kumpulan: Senarai<(Teks, Senarai<Nombor>)> = [];
    untuk (kunci, nilai) dalam s {
        biar ubah dijumpai = salah;
        biar ubah baru: Senarai<(Teks, Senarai<Nombor>)> = [];
        untuk (k, vs) dalam kumpulan {
            kalau k == kunci {
                baru = baru.tambah((k, vs.tambah(nilai)));
                dijumpai = betul;
            } lain {
                baru = baru.tambah((k, vs));
            }
        }
        kalau !dijumpai {
            baru = baru.tambah((kunci, [nilai]));
        }
        kumpulan = baru;
    }
    kumpulan
}

fungsi periksa_had_kadar(
