    masa_kini: Nombor,
    tetingkap: Nombor,
    had: Nombor
) -> Benar kesan Bersih {
    biar terkini = percubaan.tapis(fungsi(masa: Nombor) -> Benar {
        masa_kini - masa < tetingkap
    });
    terkini.panjang() < had
}

fungsi susun_sisipan(s: Senarai<Nombor>) -> Senarai<Nombor> kesan Bersih {
    s.lipat([], fungsi(disusun: Senarai<Nombor>, x: Nombor) -> Senarai<Nombor> {
        biar ubah hasil: Senarai<Nombor> = [];
        biar ubah disisip = salah;
        untuk item dalam disusun {
            kalau !disisip && x <= item {
                hasil = hasil.tambah(x);
                disisip = betul;
            }
            hasil = hasil.tambah(item);
        }
        kalau !disisip {
            hasil = hasil.tambah(x);
        }
        hasil
    })
}

