fungsi nilai_ungkapan(u: Ungkapan) -> Nombor kesan Bersih {
    padan u {
        Nombor(n) -> n,
        Tambah(k, ka) -> nilai_ungkapan(k) + nilai_ungkapan(ka),
        Tolak(k, ka) -> nilai_ungkapan(k) - nilai_ungkapan(ka),
        Darab(k, ka) -> nilai_ungkapan(k) * nilai_ungkapan(ka),
    }
}

