fungsi cuba_semula<T>(
    f: Fn() -> Hasil<T, Teks>,
    cubaan_max: Nombor
) -> Hasil<T, Teks> kesan Tulis {
    biar ubah i = 0;
    selagi i < cubaan_max {
        padan f() {
            Ok(nilai) -> { pulang Ok(nilai); },
            Ralat(e) -> {
                cetak("Percubaan ");
                cetak(i + 1);
                cetak(" gagal: ");
                cetak(e);
                cetak("\n");
            },
        }
        i = i + 1;
    }
