fungsi format_nombor(n: Nombor) -> Teks kesan Bersih {
    biar teks = nombor_ke_teks(n);
    biar panjang = teks.panjang();
    kalau panjang <= 3 {
        pulang teks;
    }
    biar ubah hasil = "";
    biar ubah kiraan = 0;
    untuk i dalam (0..panjang).balik() {
        kalau kiraan > 0 && kiraan % 3 == 0 {
            hasil = "," + hasil;
        }
        hasil = teks[i] + hasil;
        kiraan = kiraan + 1;
    }
    hasil
}

