fungsi hurai_argumen(args: Senarai<Teks>) -> Senarai<Pilihan> kesan Bersih {
    biar ubah hasil: Senarai<Pilihan> = [];
    biar ubah i = 0;
    selagi i < args.panjang() {
        biar arg = args[i];
        kalau arg.bermula_dengan("--") {
            biar nama = arg.potong_teks(2, arg.panjang());
            biar nilai = kalau i + 1 < args.panjang() && !args[i + 1].bermula_dengan("--") {
                i = i + 1;
                Ada(args[i])
            } lain {
                Tidak
            };
            hasil = hasil.tambah(Pilihan { nama: nama, nilai: nilai });
        }
        i = i + 1;
    }
    hasil
}

fungsi buat_memo<A, B>(
    f: Fn(A) -> B
) -> Fn(A) -> B kesan Bersih {
    biar ubah cache: Senarai<(A, B)> = [];

    fungsi memo(x: A) -> B {
        biar carian = cache.cari(fungsi(item: (A, B)) -> Benar {
            biar (k, _) = item;
            k == x
        });
        padan carian {
            Ada((_, v)) -> v,
            Tidak -> {
                biar hasil = f(x);
                cache = cache.tambah((x, hasil));
                hasil
            },
        }
    }
    memo
}

