    untuk aksara dalam ic.ke_senarai_aksara() {
        kalau !adalah_digit(aksara) {
            pulang Ralat("IC mesti mengandungi digit sahaja");
        }
    }
    biar tahun = ic.potong_teks(0, 2);
    biar bulan = ic.potong_teks(2, 4);
    biar hari = ic.potong_teks(4, 6);
    padan tukar_ke_nombor(bulan) {
        Ada(b) kalau b >= 1 && b <= 12 -> Ok(betul),
        _ -> Ralat("Bulan tidak sah"),
    }
}

fungsi cantum_teratur(
    a: Senarai<Nombor>,
    b: Senarai<Nombor>
) -> Senarai<Nombor> kesan Bersih {
    padan (a, b) {
        ([], y) -> y,
        (x, []) -> x,
        ([x, ..xa], [y, ..ya]) kalau x <= y -> {
            [x].gabung(cantum_teratur(xa, [y].gabung(ya)))
        },
        ([x, ..xa], [y, ..ya]) -> {
            [y].gabung(cantum_teratur([x].gabung(xa), ya))
        },
    }
}

