        Ralat(e) -> Ralat("Baca gagal: {e}"),
        Ok(data) -> {
            biar baris = data.pecah("\n");
            biar diproses = baris
                .tapis(fungsi(b: Teks) -> Benar { b.panjang() > 0 })
                .peta(fungsi(b: Teks) -> Teks { b.huruf_besar() });
            biar output = diproses.gabung_ke_teks("\n");
            padan tulis_ke_fail(fail_output, output) {
                Ok(_) -> Ok(diproses.panjang()),
                Ralat(e) -> Ralat("Tulis gagal: {e}"),
            }
        },
    }
}

