fungsi peta_letak<K, V>(p: Peta<K, V>, kunci: K, nilai: V) -> Peta<K, V> kesan Bersih {
    Peta { data: p.data.tambah((kunci, nilai)) }
}

fungsi peta_ambil<K, V>(p: Peta<K, V>, kunci: K) -> Mungkin<V> kesan Bersih {
    biar hasil = p.data.cari(fungsi(item: (K, V)) -> Benar {
        biar (k, _) = item;
        k == kunci
    });
    padan hasil {
        Ada((_, v)) -> Ada(v),
