    }
}

fungsi selang_seli(
    a: Senarai<Nombor>,
    b: Senarai<Nombor>
) -> Senarai<Nombor> kesan Bersih {
    biar panjang = kalau a.panjang() > b.panjang() { a.panjang() } lain { b.panjang() };
    biar ubah hasil: Senarai<Nombor> = [];
    untuk i dalam 0..panjang {
        kalau i < a.panjang() { hasil = hasil.tambah(a[i]); }
        kalau i < b.panjang() { hasil = hasil.tambah(b[i]); }
    }
    hasil
}

fungsi bahagi_kumpulan(
    s: Senarai<Nombor>,
    saiz: Nombor
) -> Senarai<Senarai<Nombor>> kesan Bersih {
    biar ubah hasil: Senarai<Senarai<Nombor>> = [];
    biar ubah i = 0;
    selagi i < s.panjang() {
        biar akhir = kalau i + saiz > s.panjang() { s.panjang() } lain { i + saiz };
        hasil = hasil.tambah(s.potong(i, akhir));
        i = i + saiz;
    }
    hasil
}

fungsi putar_senarai(s: Senarai<Nombor>, n: Nombor) -> Senarai<Nombor> kesan Bersih {
    kalau s.panjang() == 0 {
        pulang s;
    }
    biar pos = n % s.panjang();
    biar belakang = s.potong(pos, s.panjang());
    biar depan = s.potong(0, pos);
    belakang.gabung(depan)
}

